-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

create policy "participants read return items" on public.return_items
  as permissive
  for select
  to public
  using ((EXISTS ( SELECT 1
   FROM public.returns r
     JOIN public.orders o ON o.id = r.order_id
  WHERE r.id = return_items.return_id AND ((( SELECT auth.uid() AS uid)) = o.buyer_id OR (( SELECT auth.uid() AS uid)) = o.seller_id OR ( SELECT public.is_admin() AS is_admin)))));
